  "segs": [ {
    "utf8": "它這個很特殊的一個做法 "
  } ]
}, {
  "tStartMs": 1753551,
  "dDurationMs": 968,
  "segs": [ {
    "utf8": "它就這樣做"
  } ]
}, {
  "tStartMs": 1754519,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "就是有三種不同的人"
  } ]
}, {
  "tStartMs": 1756421,
  "dDurationMs": 1418,
  "segs": [ {
    "utf8": "第一種人叫做觀察 "
  } ]
}, {
  "tStartMs": 1757839,
  "dDurationMs": 1468,
  "segs": [ {
    "utf8": "觀察的意思就是說"
  } ]
}, {
  "tStartMs": 1759307,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "他知道這邊有誰孤獨 "
  } ]
}, {
  "tStartMs": 1760909,
  "dDurationMs": 1852,
  "segs": [ {
    "utf8": "這個不是有給職"
  } ]
}, {
  "tStartMs": 1762761,
  "dDurationMs": 834,
  "segs": [ {
    "utf8": "它就是一個"
  } ]
}, {
  "tStartMs": 1763595,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "比如說在這個社區的書店的老闆"
  } ]
}, {
  "tStartMs": 1765697,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "像我們台灣就里長"
  } ]
}, {
  "tStartMs": 1767499,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "又或者說機車行的老闆"
  } ]
}, {
  "tStartMs": 1769184,
  "dDurationMs": 1651,
  "segs": [ {
    "utf8": "因為他們就是長期以來 "
  } ]
}, {
  "tStartMs": 1770835,
  "dDurationMs": 1118,
  "segs": [ {
    "utf8": "就是都在這裡"
  } ]
}, {
  "tStartMs": 1771953,
  "dDurationMs": 2636,
  "segs": [ {
    "utf8": "所以他們會認識誰"
  } ]
}, {
  "tStartMs": 1774589,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "所以他們有點像叫社區的眼睛"
  } ]
}, {
  "tStartMs": 1776374,
  "dDurationMs": 1151,
  "segs": [ {
    "utf8": "所以他會回報說 "
  } ]
}, {
  "tStartMs": 1777525,
  "dDurationMs": 2369,
  "segs": [ {
    "utf8": "有誰現在 就是以"
  } ]
}, {
  "tStartMs": 1779894,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "他們當然會有一個"
  } ]
}, {
  "tStartMs": 1780895,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "什麼幾小時的一個訓練 "
  } ]
}, {
  "tStartMs": 1782380,
  "dDurationMs": 918,
  "segs": [ {
    "utf8": "告訴他們講說"
  } ]
}, {
  "tStartMs": 1783298,
  "dDurationMs": 967,
  "segs": [ {
    "utf8": "是什麼時候其實 "
  } ]
}, {
  "tStartMs": 1784265,
  "dDurationMs": 1235,
  "segs": [ {
    "utf8": "最好能夠稍微通報"
  } ]
}, {
  "tStartMs": 1785500,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "並不是用監視的角度"
  } ]
}, {
  "tStartMs": 1787101,
  "dDurationMs": 1085,
  "segs": [ {
    "utf8": "是用關懷的角度 "
  } ]
}, {
  "tStartMs": 1788186,
  "dDurationMs": 1118,
  "segs": [ {
    "utf8": "通報也不是什麼"
  } ]
}, {
  "tStartMs": 1789304,
  "dDurationMs": 800,
  "segs": [ {
    "utf8": "通報給社工"
  } ]
}, {
  "tStartMs": 1790104,
  "dDurationMs": 718,
  "segs": [ {
    "utf8": "我跟你說 社工累死"
  } ]
}, {
  "tStartMs": 1790822,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "絕對不是"
  } ]
}, {
  "tStartMs": 1791806,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "再來通報給這個"
  } ]
}, {
  "tStartMs": 1792707,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "中間這一個人叫Link Worker"
  } ]
}, {
  "tStartMs": 1794292,
  "dDurationMs": 1351,
  "segs": [ {
    "utf8": "他是有給職的 "
  } ]
}, {
  "tStartMs": 1795643,
  "dDurationMs": 951,
  "segs": [ {
    "utf8": "他是有給職"
  } ]
}, {
  "tStartMs": 1796594,
  "dDurationMs": 1202,
  "segs": [ {
    "utf8": "就是我剛說一年要處理"
  } ]
}, {
  "tStartMs": 1797796,
  "dDurationMs": 1418,
  "segs": [ {
    "utf8": "兩百到兩百五十個案件 "
  } ]
}, {
  "tStartMs": 1799214,
  "dDurationMs": 1484,
  "segs": [ {
    "utf8": "他就會去訪視"
  } ]
}, {
  "tStartMs": 1800698,
  "dDurationMs": 868,
  "segs": [ {
    "utf8": "他訪視這些人 "
  } ]
}, {
  "tStartMs": 1801566,
  "dDurationMs": 1435,
  "segs": [ {
    "utf8": "也不是把它當做疾病"
  } ]
}, {
  "tStartMs": 1803001,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "就好像我們現在聯醫 "
  } ]
}, {
  "tStartMs": 1804002,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "有在做社會處方箋"
  } ]
}, {
  "tStartMs": 1805403,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "就是會開處方箋給他"
  } ]
}, {
  "tStartMs": 1807105,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "不是給他吃藥什麼 都不是"
  } ]
}, {
  "tStartMs": 1808807,
  "dDurationMs": 767,
  "segs": [ {
    "utf8": "是告訴他說 "
  } ]
}, {
  "tStartMs": 1809574,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "你可以去看什麼展"
  } ]
}, {
  "tStartMs": 1810792,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "可以去看什麼秀"
  } ]
}, {
  "tStartMs": 1811793,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "但是如果只是看展跟看秀"
  } ]
}, {
  "tStartMs": 1813294,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "這個不一定有解決孤獨"
  } ]
}, {
  "tStartMs": 1814596,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "因為他看完他就回來了"
  } ]
}, {
  "tStartMs": 1815997,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "他可能就是孤單一人"
  } ]
}, {
  "tStartMs": 1817499,
  "dDurationMs": 2085,
  "segs": [ {
    "utf8": "所以他們在訪視的過程當中 "
  } ]
}, {
  "tStartMs": 1819584,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "會組團"
  } ]
}, {
  "tStartMs": 1820802,
  "dDurationMs": 1918,
  "segs": [ {
    "utf8": "我覺得這是最有趣 "
  } ]
}, {
  "tStartMs": 1822720,
  "dDurationMs": 1085,
  "segs": [ {
    "utf8": "他平均一個案子"
  } ]
}, {
  "tStartMs": 1823805,
  "dDurationMs": 2252,
  "segs": [ {
    "utf8": "可能是訪視三次到六次 "
  } ]
}, {
  "tStartMs": 1826057,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "前三次會陪著你"
  } ]
}, {
  "tStartMs": 1827158,
  "dDurationMs": 3704,
  "segs": [ {
    "utf8": "他會把跟你有類似背景的人組團"
  } ]
}, {
  "tStartMs": 1830862,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "然後組團之後 "
  } ]
